#!/usr/bin/env node
// Build the claude.ai/design project payload from the vanilla catalog runtime.
//
// The catalog is framework-neutral: `catalog-runtime/italki-ui.js` installs
// `window.ITalkiUI`, a set of ~175 render functions that return HTML strings,
// and `catalog-runtime/contracts.js` installs `window.ITalkiUIContracts`, which
// the runtime asserts every prop against. claude.ai/design renders designs
// through React, so this script emits React wrappers around those renderers
// (the "custom-vanilla-react" shape) plus one static preview card per
// component, generated by actually calling the renderer.
//
// This script exists because the previous upload was produced ad hoc and never
// committed — when it had to be reproduced, it could not be. Keep it committed.
//
//   node maintenance/scripts/build-ds-project.mjs --out maintenance/ds-project
//
// Output layout (what the app's self-check consumes):
//   _ds_bundle.js      IIFE → window.ItalkiUI (React wrappers)
//   _ds_bundle.css     the vanilla stylesheet
//   styles.css         @imports the closure a rendered design receives
//   tokens/tokens.css  the token layer
//   components/<slug>/<Name>/<Name>.{html,jsx,d.ts,prompt.md}
//   _ds_needs_recompile

import { mkdirSync, readFileSync, writeFileSync, rmSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';

const argv = process.argv.slice(2);
const flag = (n, d) => { const i = argv.indexOf(`--${n}`); return i < 0 ? d : argv[i + 1]; };
const REPO = resolve(flag('repo', '.'));
const OUT = resolve(flag('out', 'maintenance/ds-project'));
const RUNTIME = join(REPO, 'catalog-runtime');

// ── load the vanilla runtime under a stub window ──────────────────────────
// The renderers only build strings; the interactive handlers touch
// global.document, which stays undefined and is never called here.
const contractsSrc = readFileSync(join(RUNTIME, 'contracts.js'), 'utf8');
const runtimeSrc = readFileSync(join(RUNTIME, 'italki-ui.js'), 'utf8');
const sandbox = {};
sandbox.window = sandbox;
new Function('window', 'global', `${contractsSrc}\n${runtimeSrc}`)(sandbox, sandbox);
const UI = sandbox.ITalkiUI;
const CONTRACTS = sandbox.ITalkiUIContracts.components;
if (!UI) throw new Error('window.ITalkiUI was not installed — check catalog-runtime/italki-ui.js');

