// Which enum prop is the interesting visual axis, in preference order. `state`
// and `demo` are documentation-only knobs and never lead.
const AXIS_ORDER = ['variant', 'tone', 'checked', 'value', 'type', 'placement', 'orientation', 'shape', 'size', 'density', 'status'];
const AXIS_SKIP = new Set(['state', 'demo', 'disabled', 'closable', 'banner', 'removable', 'interactive', 'open', 'loading', 'toggleMode']);

function axisFor(key) {
  const contract = CONTRACTS[key] ?? {};
  const props = contract.props ?? {};
  // `props` documents enums for subcomponents too (slider lists `orientation`
  // and `mode`, which only slider.vertical / slider.range accept), so the axis
  // must be intersected with acceptedProps or the sweep renders invalid props.
  const accepted = new Set(contract.acceptedProps ?? []);
  for (const cand of AXIS_ORDER) {
    if (AXIS_SKIP.has(cand) || !accepted.has(cand)) continue;
    const values = props[cand];
    if (Array.isArray(values) && values.length > 1 && values.length <= 9) return [cand, values];
  }
  return [null, []];
}

// ── render one component's cells ──────────────────────────────────────────
const escape = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

// The renderers emit page-relative asset URLs (`src="Assets/Icons/x.svg"`),
// which is right for a design rendered at the project root but wrong for a card
// three directories down — there it would resolve to
// components/<slug>/<Name>/Assets/…. Rewrite to the card's depth, driven by the
// contract's own assetRoots so a new root is picked up automatically.
const ASSET_ROOTS = sandbox.ITalkiUIContracts.assetRoots ?? ['Assets/'];
const CARD_DEPTH = '../../../';
function localizeAssets(html) {
  let out = html;
  for (const root of ASSET_ROOTS) {
    const top = root.split('/')[0];
    out = out.split(`="${top}/`).join(`="${CARD_DEPTH}${top}/`);
    out = out.split(`url(${top}/`).join(`url(${CARD_DEPTH}${top}/`);
  }
  return out;
}

function cellsFor(c) {
  const base = BASE[c.fn] ?? {};
  const explicit = CELLS[c.fn];
  const [axis, values] = explicit ? [null, []] : axisFor(c.key);
  const cells = [];
  const push = (label, props) => {
    try {
      const html = UI[c.fn](props);
      if (typeof html === 'string' && html.trim()) cells.push({ label, html, props });
      else cells.push({ label, html: '', error: 'renderer returned nothing' });
    } catch (e) {
      cells.push({ label, html: '', error: e.message });
    }
  };
  if (explicit) {
    for (const [label, props] of explicit) push(label, { ...base, ...props });
    return { cells, axis: null };
  }
  if (axis) for (const v of values) push(`${axis} = ${v}`, { ...base, [axis]: v });
  else push('Default', { ...base });
  // A disabled cell whenever the contract accepts one — it is the state most
  // often needed and least often obvious from the axis sweep.
  const accepted = CONTRACTS[c.key]?.acceptedProps ?? [];
  if (accepted.includes('disabled')) push('disabled', { ...base, disabled: true });
  return { cells, axis };
}

// ── emit ──────────────────────────────────────────────────────────────────
if (existsSync(OUT)) rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });
const write = (rel, body) => { const p = join(OUT, rel); mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, body); };

const report = { ok: [], failed: [] };

for (const c of COMPONENTS) {
  if (typeof UI[c.fn] !== 'function') { report.failed.push(`${c.name}: no renderer ${c.fn}`); continue; }
  const { cells, axis } = cellsFor(c);
  const bad = cells.filter((x) => x.error);
  if (bad.length === cells.length) { report.failed.push(`${c.name}: every cell failed — ${bad[0].error}`); continue; }
  if (bad.length) report.failed.push(`${c.name}: ${bad.length}/${cells.length} cells failed — ${bad[0].error}`);

  const dir = `components/${c.slug}/${c.name}`;
  const contract = CONTRACTS[c.key] ?? {};
  const accepted = contract.acceptedProps ?? [];
  const enums = contract.props ?? {};

  // Card — static HTML, produced by the real renderer.
  write(`${dir}/${c.name}.html`, `<!-- @dsCard group="${c.group}" -->
<!doctype html>
<html lang="en"><head>
<meta charset="utf-8">
<title>${c.name} — italki UI Kit</title>
<link rel="stylesheet" href="../../../styles.css">
<style>
  *{box-sizing:border-box}
  body{margin:0;padding:var(--ui-space-6,24px);background:var(--ui-color-page,#FFFFFF);font-family:"Noto Sans",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ui-color-text)}
  .ds-grid{display:flex;flex-wrap:wrap;gap:var(--ui-space-6,24px) var(--ui-space-8,32px);align-items:flex-start}
  .cell{min-width:0}
  /* Anchored overlays are open in a static card, so the reservation must be
     real in every direction. Sideways placements push a whole surface (up to
     320px) clear of the trigger, which no padding on a shrink-to-fit cell can
     absorb — so each takes half a row and gets the slack horizontally, and
     only the vertical clearance is padded. */
  .cell--anchored{flex:0 0 100%;width:100%}
  .cell--anchored>.cell-body{display:grid;place-items:center;padding:var(--ui-space-12,96px) 0}
  /* Full-surface overlays take their own row so width:100% has a width. */
  .cell--surface{flex:0 0 100%;width:100%}
  .cell-label{font-size:12px;line-height:16px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--ui-color-secondary);margin:0 0 var(--ui-space-2,8px)}
</style>
</head><body>
<div class="ds-grid">
${cells.filter((x) => !x.error).map((x) => `  <div class="cell${STAGE[c.fn] ? ` cell--${STAGE[c.fn]}` : ''}"><div class="cell-label">${escape(x.label)}</div><div class="cell-body">${localizeAssets(x.html)}</div></div>`).join('\n')}
</div>
</body></html>
`);

  // Re-export stub — the app resolves the component off the global.
  write(`${dir}/${c.name}.jsx`, `// Re-export of the italki UI Kit ${c.name}. Implementation is in the root _ds_bundle.js (window.ItalkiUI).\nObject.assign(window, { ${c.name}: window.ItalkiUI.${c.name} });\n`);

  // Contract — straight from contracts.js, which the runtime itself asserts.
  const propLines = accepted.map((p) => {
    const values = enums[p];
    const type = Array.isArray(values)
      ? values.map((v) => (typeof v === 'string' ? JSON.stringify(v) : String(v))).join(' | ')
      : /^(items|options|rows|columns|members|pages)$/.test(p) ? 'unknown[]'
      : /^(disabled|loading|open|closable|banner|removable|interactive|iconOnly|decorative|current)$/.test(p) ? 'boolean'
      : 'React.ReactNode';
    return `  ${p}?: ${type};`;
  });
  write(`${dir}/${c.name}.d.ts`, `import * as React from 'react';

/**
 * ${c.name} — italki UI Kit (vanilla catalog runtime, React wrapper).
 * Props are validated at runtime against contracts.js; an unknown prop throws.
 */
export interface ${c.name}Props {
${propLines.join('\n') || '  [key: string]: unknown;'}
}

export declare const ${c.name}: React.ComponentType<${c.name}Props>;
`);

  const axisNote = axis ? `\nPrimary variant axis: \`${axis}\` — ${enums[axis].map((v) => `\`${v}\``).join(', ')}.\n` : '';

  // The props interface names structured props (items, sections, footer…) but
  // cannot express their shapes, and a generator that guesses a shape produces
  // rows the renderer silently degrades — the teacher-search template invented
  // {label, secondary} chat items and lost the avatars the Catalog shows. So
  // every prompt carries the exact props its card rendered with. Long strings
  // (rendered HTML passed into slots) are elided but keep their head, which is
  // enough to see that a slot takes rendered markup from another component.
  const elide = (value) => {
    if (typeof value === 'string' && value.length > 96) return `${value.slice(0, 93)}…`;
    if (Array.isArray(value)) return value.map(elide);
    if (value && typeof value === 'object') {
      return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, elide(v)]));
    }
    return value;
  };
  const exampleCell = cells.find((x) => !x.error && x.props);
  const exampleNote = exampleCell ? `
## Example — the exact props behind the card's “${exampleCell.label}” cell

\`\`\`json
${JSON.stringify(elide(exampleCell.props), null, 2)}
\`\`\`

Structured props (arrays, section/item objects, HTML slot strings) must follow
these shapes — inventing a leaner shape renders, but silently drops the parts
the shape carries (leading avatars, prefixes, dividers). Values ending in \`…\`
are elided rendered-HTML strings; build them with \`window.ItalkiUI.raw.<fn>()\`.
` : '';
  write(`${dir}/${c.name}.prompt.md`, `${c.name} from the italki UI Kit. Use via \`window.ItalkiUI.${c.name}\` (bundle loaded from the root \`_ds_bundle.js\`). No provider wrapper is needed — the component renders the catalog runtime's own markup and reads its styling from \`styles.css\`.
${axisNote}
## Props

\`\`\`ts
interface ${c.name}Props {
${propLines.join('\n')}
}
\`\`\`

Props are asserted at runtime against \`contracts.js\`: passing a prop this
component does not accept throws \`${c.key} does not accept prop <name>\`. The
accepted set above is therefore exhaustive.
${exampleNote}
## Cells shown on the card

${cells.filter((x) => !x.error).map((x) => `- ${x.label}`).join('\n')}
`);

  report.ok.push(c.name);
}

// ── bundle: React wrappers over the vanilla renderers ─────────────────────
const wrappers = COMPONENTS.filter((c) => typeof UI[c.fn] === 'function').map((c) =>
  `    ${c.name}: wrap(${JSON.stringify(c.fn)}),`).join('\n');

// The first-line header is a contract with the app's self-check: it reads
// `namespace` to resolve the global and `components[]` (name + sourcePath) to
// register what the design agent may build with. Getting the shape wrong is
// silent — the cards still render, but the agent sees an empty design system.
const bundleHeader = {
  namespace: 'ItalkiUI',
  components: COMPONENTS.filter((c) => report.ok.includes(c.name)).map((c) => ({
    name: c.name,
    sourcePath: `components/${c.slug}/${c.name}/${c.name}.jsx`,
  })),
  builtBy: 'maintenance/scripts/build-ds-project.mjs',
  source: 'catalog-runtime/italki-ui.js',
};

write('_ds_bundle.js', `/* @ds-bundle: ${JSON.stringify(bundleHeader)} */
(function (global) {
  "use strict";
  // The vanilla catalog runtime, inlined verbatim.
${contractsSrc.replace(/^window\./m, 'global.')}
${runtimeSrc.replace(/\}\)\(window\);\s*$/, '})(global);')}
  var UI = global.ITalkiUI;
  var React = global.React;
  if (!React) throw new Error('window.React must be loaded before _ds_bundle.js');
  // Each component renders the runtime's HTML string. The renderers are pure
  // string builders, so this is a faithful mount — interactive behaviour comes
  // from the runtime's own delegated document listeners.
  function wrap(fn) {
    function Component(props) {
      var html = '';
      try { html = UI[fn](props || {}); }
      catch (e) { html = '<div style="color:var(--ui-color-error,#D3382F);font:12px system-ui">' + (e && e.message || e) + '</div>'; }
      return React.createElement('div', {
        className: 'italki-ui-embed',
        dangerouslySetInnerHTML: { __html: html },
      });
    }
    Component.displayName = fn;
    return Component;
  }
  global.ItalkiUI = Object.assign({}, {
${wrappers}
  }, { raw: UI, contracts: global.ITalkiUIContracts });
})(window);
`);

// ── README — the design agent reads this ──────────────────────────────────
// Generated, not hand-written: every component name, prop value and token below
// comes from the same contracts.js the runtime asserts against, so it cannot
// drift from the implementation.
const byGroup = {};
for (const c of COMPONENTS) if (report.ok.includes(c.name)) (byGroup[c.group] ??= []).push(c.name);
// Per-component, never a union: `variant` means nine things on Button and four
// on Avatar, so a merged row would be actively misleading. Each row names the
// component it is read from, and how many others share the prop.
const axisRow = (prop, key) => {
  const contract = CONTRACTS[key] ?? {};
  const values = (contract.props?.[prop] ?? []).map((v) => `\`${v}\``).join(' · ');
  const shared = COMPONENTS.filter((c) => (CONTRACTS[c.key]?.acceptedProps ?? []).includes(prop)).length;
  return { values, shared };
};
const axisTable = [
  ['size', 'button', 'Button'],
  ['shape', 'button', 'Button'],
  ['variant', 'button', 'Button'],
  ['tone', 'tag', 'Tag'],
  ['status', 'text-input', 'TextInput'],
  ['placement', 'tooltip', 'Tooltip'],
].map(([prop, key, label]) => {
  const { values, shared } = axisRow(prop, key);
  return `| \`${prop}\` | ${label} | ${values} | ${shared} |`;
}).join('\n');

write('README.md', `# italki UI Kit

The italki design system, published from the framework-neutral catalog runtime
(\`catalog-runtime/italki-ui.js\`). ${report.ok.length} components.

## Using a component

Every component is on \`window.ItalkiUI\`. **No provider or wrapper is needed** —
each one renders the catalog runtime's own markup and takes its styling from
\`styles.css\`, which is already loaded.

\`\`\`jsx
const { Button, FormField, TextInput, Table } = window.ItalkiUI;

<FormField label="Email address" helper="We only use this to send lesson updates.">
  <TextInput placeholder="name@example.com" />
</FormField>
<Button label="Book trial" variant="red" shape="pill" />
\`\`\`

Note that content is passed as **props, not children** — \`label\`, \`title\`,
\`body\`, \`items\`, \`options\`, \`columns\`/\`rows\`. Check the component's
\`.d.ts\` before composing.

## Props are validated at runtime — do not invent them

Every renderer asserts its props against \`contracts.js\`. Passing a prop a
component does not accept throws immediately:

\`\`\`
Error: checkbox does not accept prop value
\`\`\`

So the prop list in each \`<Name>.d.ts\` is **exhaustive**, not indicative. Read
it before using a component; do not guess prop names from other design systems.

## The repeated prop vocabulary

The same prop names recur, but **their values are per-component** — \`variant\` is
nine things on Button and four on Avatar. Read the values below as the shape of
the vocabulary, and the component's own \`.d.ts\` as the truth.

| Prop | Values shown for | Values | Components with this prop |
|---|---|---|---|
${axisTable}

At most one \`variant="red"\` action per page or task step — it is the booking /
conversion action.

## Tokens for your own layout

Style your own containers with the published custom properties rather than hex
values. They are defined in \`tokens/tokens.css\`, which \`styles.css\` imports.

\`\`\`css
--ui-color-text        --ui-color-title       --ui-color-secondary
--ui-color-card        --ui-color-border      --ui-color-divider
--ui-color-link        --ui-color-disabled
--ui-color-error       --ui-color-info        --ui-color-success   --ui-color-warning
--ui-color-error-surface   (…and -surface for each status colour)

--ui-space-half 2px · --ui-space-1 4px · -2 8px · -3 12px · -4 16px
--ui-space-6 24px · -7 32px · -8 40px · -9 48px · -10 64px · -11 80px · -12 96px

--ui-radius-xs 4px · -md 8px · -lg 12px · -xl 16px · -2xl 24px · -full 9999px
--ui-shadow-card · -md · -lg · -xl
\`\`\`

## Assets

Icons and flags are referenced **page-relative**, which resolves correctly for a
design rendered at the project root:

\`\`\`
Assets/Icons/<name>.svg      Assets/Flags/<iso-2>.svg
\`\`\`

## Components

${Object.entries(byGroup).map(([g, names]) => `**${g}** — ${names.join(', ')}`).join('\n\n')}

## Where the detail is

\`components/<group>/<Name>/<Name>.d.ts\` is the exact prop contract;
\`<Name>.prompt.md\` lists the variants shown on its card. \`window.ItalkiUI.raw\`
exposes the runtime's full set of renderers (including subcomponents such as
\`avatar.group\`, \`slider.range\`, \`radio.group\`) and \`window.ItalkiUI.contracts\`
is the machine-readable contract the assertions come from.
`);

// ── styling ───────────────────────────────────────────────────────────────
write('_ds_bundle.css', readFileSync(join(RUNTIME, 'italki-ui.css'), 'utf8'));
write('tokens/tokens.css', readFileSync(join(RUNTIME, 'tokens.css'), 'utf8'));
write('styles.css', '@import "./tokens/tokens.css";\n@import "./_ds_bundle.css";\n');
write('_ds_needs_recompile', '{"by":"build-ds-project"}\n');

console.log(`✓ ${OUT}`);
console.log(`  components: ${report.ok.length}/${COMPONENTS.length}`);
if (report.failed.length) {
  console.log(`  issues (${report.failed.length}):`);
  for (const f of report.failed) console.log(`    ! ${f}`);
}
